          "يقول مثل ما يقول المؤذن إلا في: «حي على الصلاة، وحي على الفلاح» فيقول: «لا حول ولا قوة إلا بالله». وبعد الفراغ يصلي على النبي ﷺ ثم يقول: «اللهم رب هذه الدعوة التامة والصلاة القائمة آت محمداً الوسيلة والفضيلة وابعثه مقاماً محموداً الذي وعدته» (حلت له شفاعتي يوم القيامة).",
          "دعاء الاستفتاح: «سبحانك اللهم وبحمدك، وتبارك اسمك، وتعالى جدك، ولا إله غيرك». أو: «اللهم باعد بيني وبين خطاياي كما باعدت بين المشرق والمغرب، اللهم نقني من خطاياي كما يُنقى الثوب الأبيض من الدنس، اللهم اغسلني من خطاياي بالثلج والماء والبرد».",
          "أدعية الركوع: «سبحان ربي العظيم» (ثلاث مرات)، «سبوح قدوس رب الملائكة والروح». وعند الرفع: «سمع الله لمن حمده»، «ربنا ولك الحمد حمداً كثيراً طيباً مباركاً فيه».",
