          "قال العلماء: التوبة واجبة من كل ذنب. فإن كانت المعصية بين العبد وبين الله تعالى لا تتعلق بحق آدمي فلها ثلاثة شروط: أحدها: أن يُقلع عن المعصية. والثاني: أن يندم على فعلها. والثالث: أن يعزم أن لا يعود إليها أبداً. فإن فُقد أحد الثلاثة لم تصح توبته. وإن كانت المعصية تتعلق بآدمي فشروطها أربعة: هذه الثلاثة، وأن يبرأ من حق صاحبها؛ فإن كانت مالاً رده إليه، وإن كانت حد قذف مكنه منه أو عفا عنه، وإن كانت غيبة استحله منها.",
          "عن أبي هريرة رضي الله عنه قال: سمعت رسول الله ﷺ يقول: «والله إني لأستغفر الله وأتوب إليه في اليوم أكثر من سبعين مرة» (رواه البخاري).",
