          "وعن البراء بن عازب رضي الله عنه قال: «كان رسول الله ﷺ رجلاً مربوعاً، بعيد ما بين المنكبين، عظيم الجُمَّة إلى شحمة أذنيه، عليه حُلَّة حمراء، ما رأيت شيئاً قط أحسن منه ﷺ».",
