          "وشروط البيع سبعة: تراضي العاقدين، وأن يكون العاقد جائز التصرف، وأن تكون العين مباحة النفع مطلقاً، وأن يكون المبيع ملكاً للبائع أو مأذوناً له فيه، وأن يكون مقدوراً على تسليمه، وأن يكون المبيع معلوماً برؤية أو صفة، وأن يكون الثمن معلوماً.",
          "ويحرم الربا بنوعيه: ربا الفضل، وربا النسيئة، في الأجناس الربوية المنصوص عليها وهي: الذهب والفضة والبر والشعير والتمر والملح وما قاسه العلماء عليها بجامع الثمنية في النقدين والطعوم والكيل في الأطعمة.",
          "والغرر محرم في البيوع، وكل عقد تضمن مخاطرة أو جهالة فاحشة أو أكلاً لأموال الناس بالباطل فهو باطل ومنهي عنه."
