          "وبعد البعث محاسبون ومجزيون بأعمالهم، والدليل قوله تعالى: ﴿لِيَجْزِيَ الَّذِينَ أَسَاءُوا بِمَا عَمِلُوا وَيَجْزِيَ الَّذِينَ أَحْسَنُوا بِالْحُسْنَى﴾ [النجم: 31].",
