          "هو سيد الأولين والآخرين، وخاتم النبيين، محمد بن عبد الله بن عبد المطلب بن هاشم بن عبد مناف بن قصي بن كلاب، ينتهي نسبه الشريف إلى إسماعيل بن إبراهيم الخليل عليهما السلام.",
