          "نشأ على أكمل الأخلاق وأطهر السجايا حتى لقب في قومه بـ«الأمين»، ولما بلغ أربعين سنة نزل عليه الروح الأمين جبريل بغار حراء بأول آيات القرآن الكريم: ﴿اقْرَأْ بِاسْمِ رَبِّكَ الَّذِي خَلَقَ﴾.",
