          "ولما أتم الله به النعمة وأكمل الدين نزل قوله تعالى: ﴿الْيَوْمَ أَكْمَلْتُ لَكُمْ دِينَكُمْ وَأَتْمَمْتُ عَلَيْكُمْ نِعْمَتِي وَرَضِيتُ لَكُمُ الْإِسْلَامَ دِينًا﴾.",
          "وفي أوائل شهر ربيع الأول من السنة الحادية عشرة اشتد به المرض، فاختار الرفيق الأعلى وفاضت روحه الطاهرة يوم الاثنين 12 ربيع الأول، ودفن في حجرة عائشة رضي الله عنها.",
