          "سورة الفاتحة مكية، وهي أعظم سورة في القرآن، وتسمى أم القرآن والسبع المثاني.",
          "﴿بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ﴾: أبتدئ قراءتي مستعيناً بكل اسم لله تعالى، و(الله) هو المألوه المعبود المستحق لإفراده بالعبادة، و(الرحمن الرحيم) اسمان دالان على سعة رحمته وإحسانه التي وسعت كل شيء.",
