          "﴿مَالِكِ يَوْمِ الدِّينِ﴾: المالك لجميع الأشياء، ويوم الدين هو يوم القيامة، يوم يدان الناس بأعمالهم ويجازون عليها.",
          "﴿إِيَّاكَ نَعْبُدُ وَإِيَّاكَ نَسْتَعِينُ﴾: أي نخصك وحدك بالعبادة ونخصك وحدك بالاستعانة، فتقديم المعمول يفيد الحصر؛ فلا نعبد إلا إياك، ولا نتوكل إلا عليك، وهي سر القرآن العظيم.",
          "﴿اهْدِنَا الصِّرَاطَ الْمُسْتَقِيمَ﴾: دلنا وأرشدنا ووفقنا وثبتنا على الصراط الواضح الموصل إلى رضوانك وجنتك، وهو معرفة الحق والعمل به.",
