          "وقد دخل في الإيمان باليوم الآخر: الإيمان بكل ما أخبر به النبي ﷺ مما يكون بعد الموت؛ فيؤمنون بفتنة القبر، وبعذاب القبر ونعيمه. فأما الفتنة فإن الناس يُفتنون في قبورهم فيقال للرجل: من ربك؟ وما دينك؟ ومن نبيك؟ فيثبت الله الذين آمنوا بالقول الثابت في الحياة الدنيا وفي الآخرة، فيقول المؤمن: ربي الله، والإسلام ديني، ومحمد ﷺ نبيي. وأما المرتاب فيقول: هاه هاه لا أدري سمعت الناس يقولون شيئاً فقلته، فيُضرب بمطراق من حديد فيصيح صيحة يسمعها كل شيء إلا الإنسان ولو سمعها لصُعق.",
