          "بسم الله الرحمن الرحيم. قال ابن آجروم رحمه الله تعالى: الكلام هو: اللفظ المركب المفيد بالوضع. وأقسامه ثلاثة: اسم، وفعل، وحرف جاء لمعنى.",
          "فالاسم يُعرف: بالخفض، والتنوين، ودخول الألف واللام، وحروف الخفض وهي: من، وإلى، وعن، وعلى، وفي، ورُبَّ، والباء، والكاف، واللام، وحروف القسم وهي: الواو، والباء، والتاء.",
