          "باب معرفة علامات الإعراب: للرفع أربع علامات: الضمة، والواو، والألف، والنون. فأما الضمة فتكون علامة للرفع في أربعة مواضع: في الاسم المفرد، وجمع التكسير، وجمع المؤنث السالم، والفعل المضارع الذي لم يتصل بآخره شيء. وأما الواو فتكون علامة للرفع في موضعين: في جمع المذكر السالم، وفي الأسماء الخمسة، وهي: أبوك، وأخوك، وحموك، وفوك، وذو مال. وأما الألف فتكون علامة للرفع في تثنية الأسماء خاصة. وأما النون فتكون علامة للرفع في الفعل المضارع إذا اتصل به ضمير تثنية، أو ضمير جمع، أو ضمير المؤنثة المخاطبة.",
